package com.oms.order.service;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import com.ruoyi.common.core.constant.SecurityConstants;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;

/** One TK can cancel unshipped demand and recover shipped sources independently. */
@Service public class RefundGoodsTasks {
    @Resource RefundService refunds;
    @Resource RefundGoodsService goods;
    @Resource OrderCutoffService cutoff;
    @Resource OrderWarehouseClient inventory;
    @Resource @org.springframework.context.annotation.Lazy RefundAutomaticDecision decisions;
    private OrderRepository r(){return refunds.repository;}
    static long claimed(OrderRepository r,String c,long line,long excludedRefund){long mixed=r.db().queryForObject("SELECT COALESCE(SUM(quantity),0) FROM oms_refund_goods_task WHERE company_code=? AND order_line_id=? AND refund_id<>? AND action='CANCEL' AND state NOT IN ('DONE','CANCELED')",Long.class,c,line,excludedRefund);long single=r.db().queryForObject("SELECT COALESCE(SUM(GREATEST(cancel_quantity-cancelled_quantity,0)),0) FROM oms_refund WHERE company_code=? AND cancel_line_id=? AND id<>? AND goods_action='CANCEL' AND review_state IN ('APPROVED','STALE') AND goods_state NOT IN ('DONE','CANCELED')",Long.class,c,line,excludedRefund);return Math.addExact(mixed,single);}
    public List<Map<String,Object>> report(String c,long id){refunds.business(c,id,false);return r().db().query("SELECT id,order_line_id,shipment_line_id,action,quantity,state,cutoff_id,return_plan_id,result_message,control_version,plan_input,create_time FROM oms_refund_goods_task WHERE company_code=? AND refund_id=? ORDER BY id LIMIT 200",ROW,c,id);}
    @SuppressWarnings("unchecked") void adopt(String c,Map<String,Object> b,Map<String,Object> platform,Map<String,Object> input,String actor){
        Object raw=input.get("goods_tasks");require(raw instanceof List&&!((List<?>)raw).isEmpty()&&((List<?>)raw).size()<=100,"请明确每项货物处理范围，最多100项");
        List<Map<String,Object>> existing=r().db().query("SELECT * FROM oms_refund_goods_task WHERE company_code=? AND refund_id=? AND state<>'CANCELED' ORDER BY id FOR UPDATE",ROW,c,b.get("id"));boolean executed=existing.stream().anyMatch(t->!"PENDING".equals(text(t,"state"))||t.get("command_json")!=null||t.get("cutoff_id")!=null||t.get("return_plan_id")!=null);
        if(executed){require("MIXED".equals(text(b,"goods_action"))&&text(b,"purpose").equals(text(input,"purpose"))&&existing.size()==((List<?>)raw).size(),"已有货物执行记录，只能核对相同物理范围后重审，不能覆盖原动作");List<Map<String,Object>> proposed=new ArrayList<>();for(Object item:(List<?>)raw)proposed.add(obj(item));Set<String> seenOld=new HashSet<>();for(Map<String,Object> old:existing){String key=text(old,"action")+"/"+number(old,"order_line_id")+"/"+number(old,"shipment_line_id");require(seenOld.add(key),"原任务范围重复，请核对");Map<String,Object> matching=null;for(Map<String,Object> next:proposed)if(key.equals(text(next,"action")+"/"+number(next,"order_line_id")+"/"+number(next,"shipment_line_id")))matching=next;require(matching!=null&&number(old,"quantity")==number(matching,"quantity"),"已执行的商品来源与数量不能改变；请沿原任务核对");Map<String,Object> original=obj(old.get("plan_input"));if(!"CANCEL".equals(text(old,"action")))for(String field:Arrays.asList("store_code","return_address","return_contact"))require(text(original,field).equals(text(matching,field)),"已执行的退回仓或地址不能覆盖，请在原退回安排处理");}
            String newHash=planFingerprint(parse(text(platform,"payload")));r().db().update("UPDATE oms_refund_goods_task SET approved_hash=? WHERE company_code=? AND refund_id=? AND state NOT IN ('DONE','CANCELED')",newHash,c,b.get("id"));refunds.event(c,number(b,"id"),"GOODS_SCOPE_REVIEW","已核对原货物范围，重审最新平台内容；原任务、库存请求及执行结果保留",actor);return;}
        r().db().update("UPDATE oms_refund_goods_task SET state='CANCELED',result_message='重新审核替代尚未执行的方案' WHERE company_code=? AND refund_id=? AND state='PENDING'",c,b.get("id"));
        Map<String,Object> context=RefundFulfillment.context(r(),c,b);require(!Boolean.TRUE.equals(context.get("uncertain")),"实际出库结果尚待核对，不能确定取消与退回范围");Set<String> seen=new HashSet<>();String hash=planFingerprint(parse(text(platform,"payload")));
        for(Object item:(List<?>)raw){require(item instanceof Map,"货物处理范围无效");Map<String,Object> task=(Map<String,Object>)item;String action=text(task,"action");long lineId=number(task,"order_line_id"),source=number(task,"shipment_line_id"),qty=number(task,"quantity");
            require(Arrays.asList("CANCEL","RETURN","INTERCEPT","REFUSAL").contains(action)&&qty>0&&qty<=100000000,"请明确货物动作和数量");require(seen.add(source>0?"SOURCE/"+source:"CANCEL/"+lineId),"同一实际来源不能重复填写");
            List<Map<String,Object>> lines=r().db().query("SELECT ol.* FROM oms_order_line ol WHERE ol.company_code=? AND ol.order_id=? AND ol.id=? AND ol.platform_oid=? AND ol.gift_plan_id IS NULL AND ((ol.business_type='SALE' AND ol.exchange_id IS NULL)"+("RETURN".equals(action)?" OR "+RefundReturnSources.completedExchangeLine("ol"):"")+") FOR UPDATE",ROW,c,b.get("order_id"),lineId,b.get("platform_oid"));require(lines.size()==1,"货物范围不属于本退款的原购买商品或已完成换货的实际来源");Map<String,Object> line=lines.get(0);
            if("CANCEL".equals(action)){require(source==0,"取消未发商品应选择原商品行");long shipped=r().db().queryForObject("SELECT COALESCE(SUM(shipped_quantity),0) FROM oms_order_shipment_line WHERE company_code=? AND order_line_id=?",Long.class,c,lineId);require(qty<=number(line,"quantity")-number(line,"cancelled_quantity")-shipped-claimed(r(),c,lineId,number(b,"id")),"可取消数量不足或已被其他退款占用");}
            else{List<Map<String,Object>> sources=r().db().query("SELECT shipped_quantity FROM oms_order_shipment_line WHERE company_code=? AND id=? AND order_line_id=? FOR UPDATE",ROW,c,source,lineId);require(sources.size()==1&&qty<=number(sources.get(0),"shipped_quantity")-ReturnSourceClaims.refundUsed(r(),c,source,0,number(b,"id"))-ReturnSourceClaims.exchangeUsed(r(),c,source),"原实际发货来源额度不足或已被售后占用");required(task,"store_code",64);required(task,"return_address",500);required(task,"return_contact",200);}
            String request="CFRGT"+token();long created=r().insert("INSERT INTO oms_refund_goods_task(company_code,refund_id,order_id,order_line_id,shipment_line_id,action,quantity,approved_hash,request_id,plan_input) VALUES (?,?,?,?,?,?,?,?,?,?)",c,b.get("id"),b.get("order_id"),lineId,source==0?null:source,action,qty,hash,request,encode(task));if(r().messaging()!=null){long version=r().db().queryForObject("SELECT control_version FROM oms_refund_goods_task WHERE company_code=? AND id=?",Long.class,c,created);r().messaging().enqueue(c,"REFUND_GOODS",created,version,"REFGOODS"+b.get("id"),created+":"+version,0);}
        }
        refunds.event(c,number(b,"id"),"GOODS_SCOPE","已确认分项货物方案，取消与退回按各自原来源执行",actor);
    }
    public void scan(String c){
        if(r().messaging()==null)return;
        refunds.tx().execute(tx->{
            for(Map<String,Object> task:r().db().query("SELECT t.id,t.refund_id,t.control_version FROM oms_refund_goods_task t WHERE t.company_code=? AND t.state IN ('PENDING','WAIT_WAREHOUSE','UNKNOWN','PROCESSING') AND t.next_attempt<=NOW() AND (t.lease_until IS NULL OR t.lease_until<NOW()) AND NOT EXISTS(SELECT 1 FROM oms_message_outbox o WHERE o.company_code=t.company_code AND o.service_code='order' AND o.message_type='REFUND_GOODS' AND o.business_id=CAST(t.id AS CHAR) AND o.process_state IN ('PENDING','WAITING','PROCESSING')) ORDER BY t.next_attempt,t.id LIMIT 20 FOR UPDATE",ROW,c)){
                long id=number(task,"id"),version=number(task,"control_version")+1;
                r().db().update("UPDATE oms_refund_goods_task SET control_version=?,next_attempt=DATE_ADD(NOW(),INTERVAL 120 SECOND) WHERE company_code=? AND id=?",version,c,id);
                r().messaging().enqueue(c,"REFUND_GOODS",id,version,"REFGOODS"+task.get("refund_id"),id+":"+version,0);
            }return null;
        });
    }
    public void retry(String c,long refund,long task){refunds.business(c,refund,false);require(r().db().update("UPDATE oms_refund_goods_task SET state=IF(command_json IS NULL,'PENDING','UNKNOWN'),next_attempt=NOW(),result_message='',control_version=control_version+1 WHERE company_code=? AND refund_id=? AND id=? AND state='MANUAL' AND (lease_until IS NULL OR lease_until<NOW())",c,refund,task)==1,"任务不需要重试或正在处理");}
    public void process(String c,long id){String lease=token();Map<String,Object> task=refunds.tx().execute(tx->{List<Map<String,Object>> found=r().db().query("SELECT * FROM oms_refund_goods_task WHERE company_code=? AND id=? FOR UPDATE",ROW,c,id);if(found.isEmpty())return null;Map<String,Object> t=found.get(0);if(!Arrays.asList("PENDING","WAIT_WAREHOUSE","UNKNOWN","PROCESSING").contains(text(t,"state")))return null;if(r().db().update("UPDATE oms_refund_goods_task SET state='PROCESSING',lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND) WHERE company_code=? AND id=? AND (lease_until IS NULL OR lease_until<NOW())",lease,c,id)!=1)return null;return t;});if(task==null)return;
        try{if("CANCEL".equals(text(task,"action"))&&task.get("command_json")!=null){Map<String,Object> receipt=data(inventory.adjustmentReceipt(c,text(task,"request_id"),SecurityConstants.INNER));if("COMPLETED".equals(text(receipt,"state"))){applyReceipt(c,task,refunds.business(c,number(task,"refund_id"),false),lease,obj(task.get("command_json")),receipt);return;}}
            Map<String,Object> b=refunds.business(c,number(task,"refund_id"),false),p=refunds.platform(c,number(b,"platform_refund_id"),false);require("VALID".equals(text(p,"source_state"))&&"APPROVED".equals(text(b,"review_state"))&&text(task,"approved_hash").equals(text(b,"approved_hash"))&&number(b,"approved_version")==number(p,"version"),"退款范围或审核依据已变化，请核对原任务");require(!"CLOSED".equals(text(p,"platform_status")),"平台申请已关闭，请核对已执行货物动作");
            if("CANCEL".equals(text(task,"action"))){if(decisions!=null&&decisions.replanOvertaken(c,task,b))return;cancel(c,task,b,lease);}else{Map<String,Object> input=new LinkedHashMap<>(obj(task.get("plan_input")));input.put("control_version",b.get("control_version"));input.put("request_key",task.get("request_id"));input.put("confirmed",true);input.put("reason",b.get("review_reason"));input.put("evidence",b.get("review_evidence"));long plan=number(goods.create(c,number(b,"id"),input,"分项退回任务"),"id");r().db().update("UPDATE oms_refund_goods_task SET state='WAIT_RETURN',return_plan_id=?,result_message='已按原发货来源建立退回安排，沿用店铺合包及下发规则' WHERE company_code=? AND id=? AND lease_token=?",plan,c,id,lease);}
        }catch(IllegalArgumentException invalid){result(c,id,lease,"MANUAL",invalid.getMessage());}catch(RuntimeException unknown){result(c,id,lease,"UNKNOWN","处理结果尚未确认，将沿用原请求核对");}finally{r().db().update("UPDATE oms_refund_goods_task SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",c,id,lease);}
    }
    private void result(String c,long id,String lease,String state,String message){String safe=message==null?"请核对原任务":message.substring(0,Math.min(500,message.length()));r().db().update("UPDATE oms_refund_goods_task SET state=?,result_message=?,next_attempt=DATE_ADD(NOW(),INTERVAL 30 SECOND),control_version=control_version+1 WHERE company_code=? AND id=? AND lease_token=?",state,safe,c,id,lease);}
    private void cancel(String c,Map<String,Object> task,Map<String,Object> b,String lease){long order=number(b,"order_id"),lineId=number(task,"order_line_id");
        if(task.get("command_json")==null){
            boolean waiting=refunds.tx().execute(tx->{refunds.lockOriginal(c,number(b,"channel_id"),text(b,"platform_tid"));Map<String,Object> live=refunds.business(c,number(b,"id"),true),platform=refunds.platform(c,number(b,"platform_refund_id"),true);require("APPROVED".equals(text(live,"review_state"))&&number(live,"approved_version")==number(platform,"version")&&text(task,"approved_hash").equals(text(live,"approved_hash"))&&!"CLOSED".equals(text(platform,"platform_status")),"退款申请或已审核范围已变化，停止未执行取消");Map<String,Object> current=r().db().queryForMap("SELECT * FROM oms_refund_goods_task WHERE company_code=? AND id=? AND lease_token=? FOR UPDATE",c,task.get("id"),lease);Map<String,Object> o=r().db().queryForMap("SELECT * FROM oms_order WHERE company_code=? AND id=? FOR UPDATE",c,order);
                if(current.get("cutoff_id")!=null){String state=r().db().queryForObject("SELECT state FROM oms_order_cutoff WHERE company_code=? AND order_id=? AND id=?",String.class,c,order,current.get("cutoff_id"));if(!"COMPLETED".equals(state)){result(c,number(task,"id"),lease,"WAIT_WAREHOUSE","原发货单撤回尚未确认，保留库存占用");return true;}}
                List<Long> shipments=r().db().queryForList("SELECT DISTINCT sh.id FROM oms_order_shipment sh JOIN oms_order_shipment_line sl ON sl.company_code=sh.company_code AND sl.shipment_id=sh.id WHERE sh.company_code=? AND sh.order_id=? AND sl.order_line_id=? AND sh.status NOT IN ('VOIDED','CLOSED') AND sl.quantity>sl.shipped_quantity+sl.cancelled_quantity ORDER BY sh.id",Long.class,c,order,lineId);
                if(!shipments.isEmpty()&&"CUTTING".equals(text(o,"status"))){result(c,number(task,"id"),lease,"WAIT_WAREHOUSE","同原订单已有截单处理中，等待原仓库和库存回执；不重复创建");return true;}if(!shipments.isEmpty()){require(current.get("cutoff_id")==null,"撤回后又出现新的发货安排，请人工核对");cutoff.request(c,order,m("control_version",o.get("control_version"),"mode","REPLAN","shipment_ids",shipments,"reason","退款 "+b.get("refund_sn")+" 撤回原发货安排；保留其他商品需求"),"退款分项截单");long operation=r().db().queryForObject("SELECT cutoff_id FROM oms_order WHERE company_code=? AND id=?",Long.class,c,order);r().db().update("UPDATE oms_refund_goods_task SET cutoff_id=?,state='WAIT_WAREHOUSE',result_message='撤回共用发货安排，其他商品需求保留；仓库确认后仅取消本任务数量',next_attempt=DATE_ADD(NOW(),INTERVAL 30 SECOND) WHERE company_code=? AND id=? AND lease_token=?",operation,c,task.get("id"),lease);return true;}
                Map<String,Object> line=r().db().queryForMap("SELECT * FROM oms_order_line WHERE company_code=? AND id=? AND order_id=? FOR UPDATE",c,lineId,order);long shipped=r().db().queryForObject("SELECT COALESCE(SUM(shipped_quantity),0) FROM oms_order_shipment_line WHERE company_code=? AND order_line_id=?",Long.class,c,lineId);require(number(task,"quantity")<=number(line,"quantity")-number(line,"cancelled_quantity")-shipped,"实际未发数量已变化，请按新出库结果核对范围");String reference=text(line,"stock_reference").isEmpty()?text(b,"platform_tid"):text(line,"stock_reference");require(r().db().queryForObject("SELECT COUNT(*) FROM oms_order_line WHERE company_code=? AND order_id=? AND platform_oid=? AND sku_sn=? AND COALESCE(NULLIF(stock_reference,''),?)=?",Long.class,c,order,b.get("platform_oid"),line.get("sku_sn"),b.get("platform_tid"),reference)==1,"取消库存来源不唯一，请人工核对");
                Map<String,Object> command=m("request_id",task.get("request_id"),"mode","REDUCE","channel_id",b.get("channel_id"),"platform_tid",reference,"allocations",Collections.emptyList(),"demands",Collections.singletonList(m("platform_oid",b.get("platform_oid"),"sku_sn",line.get("sku_sn"),"quantity",task.get("quantity"))));r().db().update("UPDATE oms_refund_goods_task SET command_json=?,state='PROCESSING' WHERE company_code=? AND id=? AND lease_token=?",encode(command),c,task.get("id"),lease);task.put("command_json",command);return false;});
            if(waiting){cutoff.process(c,order);return;}
        }
        Map<String,Object> command=obj(task.get("command_json")),receipt=refunds.tx().execute(tx->{refunds.lockOriginal(c,number(b,"channel_id"),text(b,"platform_tid"));Map<String,Object> live=refunds.business(c,number(b,"id"),true),platform=refunds.platform(c,number(b,"platform_refund_id"),true);require("APPROVED".equals(text(live,"review_state"))&&number(live,"approved_version")==number(platform,"version")&&text(task,"approved_hash").equals(text(live,"approved_hash"))&&!"CLOSED".equals(text(platform,"platform_status")),"退款范围已变化，停止新库存取消，先核对原请求");return data(inventory.adjust(c,command,SecurityConstants.INNER));});applyReceipt(c,task,b,lease,command,receipt);
    }
    private void applyReceipt(String c,Map<String,Object> task,Map<String,Object> b,String lease,Map<String,Object> command,Map<String,Object> receipt){long lineId=number(task,"order_line_id"),order=number(b,"order_id");require("COMPLETED".equals(text(receipt,"state"))&&text(command,"request_id").equals(text(receipt,"request_id")),"原库存取消回执尚未确认");
        refunds.tx().execute(tx->{refunds.lockOriginal(c,number(b,"channel_id"),text(b,"platform_tid"));require(r().db().queryForObject("SELECT COUNT(*) FROM oms_refund_goods_task WHERE company_code=? AND id=? AND lease_token=? AND lease_until>NOW() FOR UPDATE",Long.class,c,task.get("id"),lease)==1,"原货物任务租约已变化，请刷新核对");Map<String,Object> line=r().db().queryForMap("SELECT * FROM oms_order_line WHERE company_code=? AND id=? AND order_id=? FOR UPDATE",c,lineId,order);Map<String,Object> selected=null;for(Map<String,Object> row:list(receipt.get("lines")))if(text(b,"platform_oid").equals(text(row,"platform_oid"))&&text(line,"sku_sn").equals(text(row,"sku_sn"))){require(selected==null,"取消回执来源重复");selected=row;}require(selected!=null,"取消回执缺少原商品行");r().db().update("UPDATE oms_order_line SET cancelled_quantity=GREATEST(cancelled_quantity,?),reserved_quantity=LEAST(reserved_quantity,?),inventory_reason='退款分项取消指定未发需求' WHERE company_code=? AND id=?",selected.get("cancelled_quantity"),selected.get("reserved_quantity"),c,lineId);result(c,number(task,"id"),lease,"DONE","指定未发数量已取消，原库存回执已确认；其他商品需求保留");RefundOrderCancellation.reconcile(r(),c,order,text(b,"refund_sn"),"退款分项截单");refunds.event(c,number(b,"id"),"SCOPE_CANCEL","任务 #"+task.get("id")+" 已取消 "+task.get("quantity")+"；库存请求 "+task.get("request_id"),"退款分项截单");long outstanding=r().db().queryForObject("SELECT COUNT(*) FROM oms_refund_goods_task WHERE company_code=? AND refund_id=? AND state NOT IN ('DONE','CANCELED')",Long.class,c,b.get("id"));if(outstanding==0)r().db().update("UPDATE oms_refund SET goods_state='DONE',state=IF(review_state='APPROVED' AND funds_state='SUCCESS','COMPLETED',state),control_version=control_version+1 WHERE company_code=? AND id=?",c,b.get("id"));RefundGuard.refresh(r(),c,number(b,"channel_id"),text(b,"platform_tid"));return null;});
    }
}
